on conflict (item_key) do update set
  source_id=excluded.source_id,
  source_url=excluded.source_url,
  source_tier=excluded.source_tier,
  levels_declared=excluded.levels_declared,
  topology_status=excluded.topology_status,
  perk_count=excluded.perk_count,
  observed_at=excluded.observed_at,
  notes=excluded.notes;

delete from public.weapon_proficiency_perks
where item_key in ('grand-sanguine-bow','grand-sanguine-crossbow','soulbleeder','soulpiercer','eldritch-bow','gilded-eldritch-bow','bow-of-destruction','crossbow-of-destruction');

